content.text:
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        l = _rng(item[0], 0, 127)
        r = _rng(item[1], 1, MAXRATE)
        if l in out:
            raise Invalid()
        out[l] = r
    return out


def _participants(x):
    if not isinstance(x, list) or len(x) < 2 or len(x) > 32:
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        v = _rng(item[0], 0, 47)
        d = _rng(item[1], 0, MAXRATE)
        if v in out:
            raise Invalid()
        out[v] = d
    tot = 0
    for d in out.values():
        tot += d
    if tot <= 0:
        raise Invalid()
    return out


def _fields(req, names):
    if type(req) is not dict or set(req.keys()) != names:
        raise Invalid()


def _err(code, rev):
    return {'status': 'error', 'code': code, 'rev': rev}


# --------------------------------------------------------------- controller


class Controller:
    def __init__(self):
        self.loaded = False
        self.n = 0
        self.linkuv = []
        self.linkcap = []
        self.rev = 0
        self.now = 0
        self.leases = {}        # id -> {owner,s,e,env,state}
        self.load_ids = set()
        self.prep = {}          # id -> (payload, base_rev, outcome)

    # -- lease book helpers --------------------------------------------

    def _used(self, l, t):
        tot = 0
        for rec in self.leases.values():
            if rec['state'] == 'live' and rec['s'] <= t < rec['e']:
                tot += rec['env'].get(l, 0)
        return tot

    def _used_profile(self, ticks):
        """Exact used(l,t) for every link at each requested tick, by sweep.

        ticks must be sorted and deduplicated.  Returns the tick list and a
        per-link list of used values aligned with it.
        """
        nl = len(self.linkcap)
        events = [[] for _ in range(nl)]
        for rec in self.leases.values():
            if rec['state'] != 'live':
                continue
            s = rec['s']
            e = rec['e']
            for l, rate in rec['env'].items():
                if rate:
                    events[l].append((s, rate))
                    events[l].append((e, -rate))
        out = []
        for l in range(nl):
            ev = sorted(events[l])
            cur = 0
            j = 0
            col = []
            for t in ticks:
                while j < len(ev) and ev[j][0] <= t:
                    cur += ev[j][1]
                    j += 1
                col.append(cur)
            out.append(col)
        return out

    def _live_ids(self):
        return sorted(i for i, rec in self.leases.items() if rec['state'] == 'live')

    def _ticks_from_now(self):
        cand = {self.now}
        for rec in self.leases.values():
            if rec['state'] == 'live':
                if rec['s'] > self.now:
                    cand.add(rec['s'])
                if rec['e'] > self.now:
                    cand.add(rec['e'])
        return sorted(cand)

    def _ticks_in_window(self, s, e):
        cand = {s}
        for rec in self.leases.values():
            if rec['state'] == 'live' and s < rec['s'] < e:
                cand.add(rec['s'])
        return sorted(cand)

    def _blocked_witness(self, newcap):
        """Link/tick at or after now where a live lease would be overbooked."""
        cand = sorted(self._ticks_from_now())
        prof = self._used_profile(cand)
        for l in range(len(self.linkcap)):
            col = prof[l]
            for ti in range(len(cand)):
                if col[ti] > newcap[l]:
                    return (l, cand[ti], col[ti])
        return None

    def _capacity_witness(self, env, s, e):
        """Link/tick in [s,e) where used(l,t)+b_l exceeds the base capacity."""
        cand = sorted(self._ticks_in_window(s, e))
        prof = self._used_profile(cand)
        for l in range(len(self.linkcap)):
            rate = env.get(l, 0)
            col = prof[l]
            for ti in range(len(cand)):
                u = col[ti]
                if u + rate > self.linkcap[l]:
                    return (l, cand[ti], u + rate)
        return None
